class FastScanner {
    static const int BUFSIZE = 1 << 16;
    char buf[BUFSIZE];
    int idx, size;
    FastScanner(): idx(0), size(0) {}
    inline char read() {
        if (idx >= size) {
            size = fread(buf, 1, BUFSIZE, stdin);
            idx = 0;
            if (size == 0) return EOF;
        }
        return buf[idx++];
    }
    int nextInt() {
        char c; int x = 0; bool neg = false;
        c = read();
        while (c <= ' ') c = read();
        if (c == '-') { neg = true; c = read(); }
        for (; c >= '0'; c = read()) x = x * 10 + (c - '0');
        return neg ? -x : x;
    }
};
