#include <bits/stdc++.h>
using namespace std;

struct FastIO {
    static const int BUFSIZE = 1 << 16;
    int idx, size;
    char buf[BUFSIZE];
    FastIO() : idx(0), size(0) {}
    inline char read() {
        if (idx >= size) {
            size = fread(buf, 1, BUFSIZE, stdin);
            idx = 0;
            if (size == 0) return EOF;
        }
        return buf[idx++];
    }
    int nextInt() {
        char c;
        int x = 0;
        bool neg = false;
        c = read();
        while (c <= ' ') c = read();
        if (c == '-') { neg = true; c = read(); }
        for (; c >= '0' && c <= '9'; c = read()) x = x * 10 + (c - '0');
        return neg ? -x : x;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    FastIO in;
    int n = in.nextInt();
    int k = in.nextInt();
    vector<int> query(n);
    for (int i = 0; i < n; ++i) query[i] = in.nextInt();

    int cost = 0;
    unordered_set<int> availableBooks;
    availableBooks.reserve(k * 2);
    vector<int> access(81, 0);
    int removable = -1;

    for (int i = 0; i < n; ++i) {
        access[query[i]]++;
    }

    for (int i = 0; i < n; ++i) {
        int currentBook = query[i];
        bool doesNotContain = availableBooks.find(currentBook) == availableBooks.end();
        if (doesNotContain) {
            cost++;
        }

        if (removable != -1) {
            availableBooks.erase(removable);
            removable = -1;
        } else if ((int)availableBooks.size() == k && doesNotContain) {
            int removableBook = -1;
            int count = k;
            unordered_set<int> known;
            known.reserve(k * 2);
            for (int j = i + 1; j < n && count > 0; ++j) {
                int book = query[j];
                if (availableBooks.find(book) != availableBooks.end() && known.find(book) == known.end()) {
                    count--;
                    known.insert(book);
                    removableBook = book;
                }
            }
            if (removableBook != -1) {
                availableBooks.erase(removableBook);
            } else {
                availableBooks.erase(availableBooks.begin());
            }
        }

        availableBooks.insert(currentBook);
        if (--access[currentBook] == 0) {
            removable = currentBook;
        }
    }

    cout << cost << '\n';
    return 0;
}

