    }
};

void solve(FastInput& in) {
    int n = in.nextInt();
    int k = in.nextInt();
    vector<int> query = in.nextIntArray(n);

    int cost = 0;
    unordered_set<int> availableBooks;
    availableBooks.reserve(k * 2);

    vector<int> access(81, 0);
    for (int book : query) access[book]++;

