        }

        if (removable != -1) {
            availableBooks.erase(removable);
            removable = -1;
        } else if ((int)availableBooks.size() == k && doesNotContain) {
            int removableBook = -1;
            int count = k;
            unordered_set<int> known;
            known.reserve(k * 2);

            for (int j = i + 1; j < n && count > 0; ++j) {
                int q = query[j];
                if (availableBooks.find(q) != availableBooks.end() && known.find(q) == known.end()) {
                    count--;
                    known.insert(q);
                    removableBook = q;
                }
            }

            if (removableBook != -1) {
                availableBooks.erase(removableBook);
            } else {
                availableBooks.erase(availableBooks.begin());
            }
        }

        availableBooks.insert(currentBook);
        if (--access[currentBook] == 0) {
            removable = currentBook;
        }
    }

    printf("%d\n", cost);
}

int main() {
    FastInput in;
    solve(in);
    return 0;
}

